import org.apache.commons.jxpath.ri.model.jdom.JDOMNodePointer;
import org.apache.commons.jxpath.ri.model.jdom.NodeNameTest;
import org.apache.commons.jxpath.ri.model.jdom.NodeTypeTest;
import org.apache.commons.jxpath.ri.model.jdom.ProcessingInstructionTest;
import org.apache.commons.jxpath.util.TypeUtils;
