import org.jdom.Namespace;
import org.jdom.ProcessingInstruction;
import org.jdom.Text;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JDOMNodePointer.testNode
 */
public class JDOMNodePointer_testNode_TriageGen2Test {

    // Mocking helper for equalStrings which is likely a private/package-private utility
    // Since we cannot modify the source, we assume it compares strings normally.
    // The method is static, so we test the logic as provided.

    @Test
    public void testNullTestReturnsTrue() {
        NodePointer pointer = mock(NodePointer.class);
        assertTrue(JDOMNodePointer.testNode(pointer, new Object(), null));
    }

    @Test
    public void testNodeNameTest_NotAnElement() {
        NodePointer pointer = mock(NodePointer.class);
        NodeNameTest test = mock(NodeNameTest.class);
        // node is not an Element
        assertFalse(JDOMNodePointer.testNode(pointer, new Object(), test));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("any");
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName(null, null, "any"));
        when(test.getNamespaceURI()).thenReturn("some-uri");

        // If wildcard and testPrefix is null, returns true
        assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_WildcardMatch() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("localName");
        element.setNamespace(new org.jdom.Namespace("prefix", "uri"));

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("prefix", "uri", "localName"));
        when(test.getNamespaceURI()).thenReturn("uri");

        assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_LocalNameMatch_NamespaceMatch() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("name", new org.jdom.Namespace("p", "uri"));

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", "uri", "name"));
        when(test.getNamespaceURI()).thenReturn("uri");

        assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_LocalNameMatch_PrefixMatch_NullNS() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("name", new org.jdom.Namespace("p", null));

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", null, "name"));
        when(test.getNamespaceURI()).thenReturn(null);

        assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_Mismatch() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("wrongName");

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("p", "uri", "rightName"));
        when(test.getNamespaceURI()).thenReturn("uri");

        assertFalse(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeTypeTest_Node() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);

        assertTrue(JDOMNodePointer.testNode(pointer, new Element("e"), test));
        assertTrue(JDOMNodePointer.testNode(pointer, new Document(new Element("e")), test));
        assertFalse(JDOMNodePointer.testNode(pointer, new Object(), test));
    }

    @Test
    public void testNodeTypeTest_Text() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);

        assertTrue(JDOMNodePointer.testNode(pointer, new Text("txt"), test));
        assertTrue(JDOMNodePointer.testNode(pointer, new CDATA("cdata"), test));
        assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_Comment() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);

        assertTrue(JDOMNodePointer.testNode(pointer, new Comment("com"), test));
        assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_PI() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);

        assertTrue(JDOMNodePointer.testNode(pointer, new ProcessingInstruction("target", "val"), test));
        assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    @Test
    public void testNodeTypeTest_UnknownType() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(999);

        assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    @Test
    public void testProcessingInstructionTest_Match() {
        NodePointer pointer = mock(NodePointer.class);
        ProcessingInstruction pi = new ProcessingInstruction("target", "value");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("target");

        assertTrue(JDOMNodePointer.testNode(pointer, pi, test));
    }

    @Test
    public void testProcessingInstructionTest_Mismatch() {
        NodePointer pointer = mock(NodePointer.class);
        ProcessingInstruction pi = new ProcessingInstruction("target", "value");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("wrong");

        assertFalse(JDOMNodePointer.testNode(pointer, pi, test));
    }

    @Test
    public void testProcessingInstructionTest_WrongNodeType() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("e");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("target");

        assertFalse(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testUnknownTestType() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTest unknownTest = mock(NodeTest.class);
        assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), unknownTest));
    }
}
